    def test_empty(self):
        self.assertEqual(solution.read_records(""), [])


class RegressionTests(unittest.TestCase):
    def test_header_only(self):
        self.assertEqual(solution.read_records("name,note\n"), [])

    def test_crlf_record_separator(self):
        self.assertEqual(
            solution.read_records("name,note\r\nAda,hello\r\n"),
            [{"name": "Ada", "note": "hello"}],
        )

    def test_embedded_crlf(self):
        self.assertEqual(
            solution.read_records('name,note\r\nAda,"one\r\ntwo"\r\n'),
            [{"name": "Ada", "note": "one\r\ntwo"}],
        )

    def test_embedded_comma(self):
        self.assertEqual(
            solution.read_records('name,note\nAda,"a,b"\n'),
            [{"name": "Ada", "note": "a,b"}],
        )

    def test_escaped_quotes(self):
        self.assertEqual(
            solution.read_records('name,note\nAda,"say ""hi"""\n'),
            [{"name": "Ada", "note": 'say "hi"'}],
        )

    def test_blank_field(self):
        self.assertEqual(
            solution.read_records("name,note\nAda,\n"),
            [{"name": "Ada", "note": ""}],
        )

    def test_multiple_records_mixed_fields(self):
        self.assertEqual(
            solution.read_records('a,b\r\n"x\ny","p,q"\r\nz,w\r\n'),
            [{"a": "x\ny", "b": "p,q"}, {"a": "z", "b": "w"}],
        )


if __name__ == "__main__":
    unittest.main()

def merge_intervals(intervals):
    """Merge overlapping or touching closed integer intervals.

    Accepts an iterable of ``(start, end)`` pairs and returns a sorted list
    of tuples in which every overlapping or touching interval has been
    combined.  A reversed interval (``start > end``) raises ``ValueError``.
    The input pairs and their container are never mutated.
    """
    items = []
    for pair in intervals:
        start, end = pair
        if start > end:
            raise ValueError("reversed interval: start > end")
        items.append((start, end))

    items.sort()

    merged = []
    for start, end in items:
        if merged and start <= merged[-1][1] + 1:
            prev_start, prev_end = merged[-1]
            if end > prev_end:
                merged[-1] = (prev_start, end)
        else:
            merged.append((start, end))
    return merged

